{"command":"mkdir -p /tmp/test_runtime
cat << 'EOF' > /tmp/test_runtime/runtime.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>
#include <dlfcn.h>
#include "/tmp/test_grammar/src/tree_sitter/parser.h"

typedef struct {
    const char *input;
    uint32_t position;
    uint32_t length;
    uint32_t row;
    uint32_t col;
} LexerState;

static void lexer_advance(TSLexer *lexer, bool skip) {
    LexerState *state = (LexerState *)lexer;
    if (state->position < state->length) {
        if (state->input[state->position] == '\n') {
            state->row++;
            state->col = 0;
        } else {
            state->col++;
        }
        state->position++;
        if (state->position < state->length) {
            lexer->lookahead = (unsigned char)state->input[state->position];
        } else {
            lexer->lookahead = 0;
        }
    } else {
        lexer->lookahead = 0;
    }
}

static void lexer_mark_end(TSLexer *lexer) {}
static uint32_t lexer_get_column(TSLexer *lexer) {
    LexerState *state = (LexerState *)lexer;
    return state->col;
}
static bool lexer_is_at_included_range_start(const TSLexer *lexer) { return false; }
static bool lexer_eof(const TSLexer *lexer) {
    LexerState *state = (LexerState *)lexer;
    return state->position >= state->length;
}

int main() {
    void *lib = dlopen("/tmp/test_grammar/parser.so", RTLD_NOW);
    if (!lib) { printf("dlopen error: %s\n", dlerror()); return 1; }
    const TSLanguage *(*get_lang)(void) = dlsym(lib, "tree_sitter_testlang");
    if (!get_lang) { printf("dlsym error\n"); return 1; }
    const TSLanguage *lang = get_lang();

    const char *code = "hello";
    LexerState ls = {
        .input = code,
        .position = 0,
        .length = strlen(code),
        .row = 0,
        .col = 0
    };
    TSLexer lexer = {
        .lookahead = (unsigned char)code[0],
        .advance = lexer_advance,
        .mark_end = lexer_mark_end,
        .get_column = lexer_get_column,
        .is_at_included_range_start = lexer_is_at_included_range_start,
        .eof = lexer_eof,
        .log = NULL
    };

    bool lex_res = lang->lex_fn(&lexer, 0);
    printf("lex result: %d, result_symbol: %u (%s)\n", lex_res, lexer.result_symbol, lang->symbol_names[lexer.result_symbol]);

    return 0;
}
EOF
gcc /tmp/test_runtime/runtime.c -o /tmp/test_runtime/runtime -ldl
/tmp/test_runtime/runtime"}

