        camel_default = "".join(x.capitalize() for x in name.split("_"))
        camel_name = input(f"? CamelCase name ({camel_default}) › ").strip() or camel_default
        title = input(f"? Title (human-readable name) ({camel_name}) › ").strip() or camel_name
        desc_default = f"{title} grammar for tree-sitter"
        desc = input(f"? Description › ").strip() or desc_default
        repo_default = f"https://github.com/tree-sitter/tree-sitter-{name}"
        repo_url = input(f"? Repository URL › ").strip() or repo_default
        funding_url = input("? Funding URL › ").strip()
        scope_default = f"source.{name}"
        scope = input(f"? TextMate scope ({scope_default}) › ").strip() or scope_default
        file_type = input(f"? File types (space-separated) ({name}) › ").strip() or name
        file_types = file_type.split()
        version = input("? Version (0.1.0) › ").strip() or "0.1.0"
        license_str = input("? License (MIT) › ").strip() or "MIT"
        author_name = input("? Author name › ").strip()
        author_email = input("? Author email › ").strip()
        author_url = input("? Author URL › ").strip()

        ts_config = {
            "grammars": [
                {
                    "name": name,
                    "camelcase": camel_name,
                    "title": title,
                    "scope": scope,
                    "file-types": file_types,
                    "highlights": ["queries/highlights.scm"]
                }
