            "metadata": {
                "version": version,
                "license": license_str,
                "description": desc,
                "authors": [
                    {
                        "name": author_name,
                        "email": author_email,
                        "url": author_url
                    }
                ],
                "links": {
                    "repository": repo_url
                }
            }
        }

        with open("tree-sitter.json", "w") as f:
            json.dump(ts_config, f, indent=2)
            f.write("\n")

        grammar_js = f"""/**
 * @file {title} grammar for tree-sitter
 * @author {author_name} <{author_email}>
 * @license {license_str}
 */

/// <reference types="tree-sitter-cli/dsl" />
// @ts-check

export default grammar({{
  name: "{name}",

  rules: {{
    // TODO: add the actual grammar rules
    source_file: $ => "hello"
  }}
}});
"""
        with open("grammar.js", "w") as f:
            f.write(grammar_js)

        return 0
    except (KeyboardInterrupt, EOFError):
        return 1
EOF"}

