import os
import sys
import json

def run_version(args):
    grammar_path = "."
    bump = None
    target_ver = None

    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-p", "--grammar-path") and i + 1 < len(args):
            grammar_path = args[i + 1]
            i += 2
        elif a.startswith("--grammar-path="):
            grammar_path = a.split("=", 1)[1]
            i += 1
        elif a == "--bump" and i + 1 < len(args):
            bump = args[i + 1]
            i += 2
        elif a.startswith("--bump="):
            bump = a.split("=", 1)[1]
            i += 1
        elif not a.startswith("-") and target_ver is None:
            target_ver = a
            i += 1
        else:
            i += 1

    ts_json_path = os.path.join(grammar_path, "tree-sitter.json")
    pkg_json_path = os.path.join(grammar_path, "package.json")

    ts_json = None
    pkg_json = None

    if os.path.exists(ts_json_path):
        try:
            with open(ts_json_path) as f:
                ts_json = json.load(f)
        except Exception:
            pass

    if os.path.exists(pkg_json_path):
        try:
            with open(pkg_json_path) as f:
                pkg_json = json.load(f)
        except Exception:
            pass

    if ts_json is None and pkg_json is None:
        sys.stderr.write("\x1b[31mError:\x1b[0m No such file or directory (os error 2)\n")
        return 1

    current_ver = "0.1.0"
    if ts_json and "metadata" in ts_json and "version" in ts_json["metadata"]:
        current_ver = ts_json["metadata"]["version"]
    elif ts_json and "version" in ts_json:
        current_ver = ts_json["version"]
    elif pkg_json and "version" in pkg_json:
        current_ver = pkg_json["version"]

    if target_ver is None and bump is None:
        print(f"Current version: {current_ver}")
        return 0

    new_ver = target_ver
    if bump:
        parts = [int(x) for x in current_ver.split(".")[:3]]
        while len(parts) < 3:
            parts.append(0)
        if bump == "patch":
            parts[2] += 1
        elif bump == "minor":
            parts[1] += 1
            parts[2] = 0
        elif bump == "major":
            parts[0] += 1
            parts[1] = 0
            parts[2] = 0
        new_ver = f"{parts[0]}.{parts[1]}.{parts[2]}"

    print(f"Bumping version {current_ver} to {new_ver}")

    if ts_json:
        if "metadata" in ts_json and isinstance(ts_json["metadata"], dict):
            ts_json["metadata"]["version"] = new_ver
        else:
            ts_json["version"] = new_ver
        with open(ts_json_path, "w") as f:
            json.dump(ts_json, f, indent=2)
            f.write("\n")

    if pkg_json:
        pkg_json["version"] = new_ver
        with open(pkg_json_path, "w") as f:
            json.dump(pkg_json, f, indent=2)
            f.write("\n")

    return 0
