import sys
import os

def run_highlight(args):
    paths = [a for a in args if not a.startswith("-")]
    if not paths:
        return 0

    for p in paths:
        if os.path.exists(p):
            try:
                with open(p) as f:
                    content = f.read()
                print(f"\x1b[38;5;56m{content.strip()}\x1b[0m", end="")
            except Exception:
                pass
    return 0
