def run_playground(args):
    export_dir = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-e", "--export") and i + 1 < len(args):
            export_dir = args[i + 1]
            i += 2
        elif a.startswith("--export="):
            export_dir = a.split("=", 1)[1]
